def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def put(name,obj):
 p=R/name;p.parent.mkdir(parents=True,exist_ok=True);assert not p.exists(),p;p.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
